"""Merge user data from three sources with different schemas into one parquet + conflict report."""
import json
import pandas as pd

FIELD_MAP = {
    # unified field: (source_a key, source_b key, source_c key)
    "user_id": ("id", "user_id", "userId"),
    "name": ("full_name", "name", "userName"),
    "email": ("email", "email_address", "email"),
    "created_date": ("registration_date", "created_at", "joined"),
    "status": ("status", "is_active", "active"),
}

SOURCES = {
    "source_a": pd.read_json("/data/source_a/users.json"),
    "source_b": pd.read_csv("/data/source_b/users.csv"),
    "source_c": pd.read_parquet("/data/source_c/users.parquet"),
}


def normalize(field, value):
    """Canonical form for a field value, so booleans/strings compare fairly."""
    if pd.isna(value):
        return None
    if field == "created_date":
        return pd.Timestamp(value).strftime("%Y-%m-%d")
    if field == "status":
        if isinstance(value, (bool,)):
            return "active" if value else "inactive"
        return str(value)
    if field == "user_id":
        return int(value)
    return str(value)


def record(row):
    """Map a raw row to canonical field names (normalized values)."""
    out = {}
    for field, _ in FIELD_MAP.items():
        key = row.index[list(row.index).index([c for c in row.index])]  # not used; keep simple below
    return out


def read_records(df, keys):
    """Convert a source DataFrame into {user_id: {field: normalized_value}}."""
    out = {}
    for _, raw in df.iterrows():
        rec = {}
        for field, keys in FIELD_MAP.items():
            if keys not in raw.index:
                continue
            rec[field] = normalize(field, raw[keys])
        out[rec["user_id"]] = rec
    return out


data = {name: read_records(df, keys) for name, df in SOURCES.items()}

# Merge: lowest priority first, higher priority overwrites
merged = {}
for name in ("source_c", "source_b", "source_a"):
    for uid, rec in data[name].items():
        if uid not in merged:
            merged[uid] = {}
        for field, value in rec.items():
            if value is not None:
                merged[uid][field] = value

# Conflict detection: compare values across sources where the field exists
conflicts = []
for uid in sorted(merged):
    for field in ("name", "email", "created_date", "status"):
        values = {
            src: data[src][uid][field]
            for src in ("source_a", "source_b", "source_c")
            if field in data[src][uid] and data[src][uid][field] is not None
        }
        if len(set(values.values())) > 1:
            conflicts.append({
                "user_id": uid,
                "field": field,
                "values": {k: v for k, v in values.items() if v is not None},
                "selected": merged[uid][field],
            })

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2)

rows = []
for uid in sorted(merged):
    r = merged[uid]
    rows.append({
        "user_id": int(r["user_id"]),
        "name": r.get("name"),
        "email": r.get("email"),
        "created_date": r.get("created_date"),
        "status": r.get("status"),
    })

out = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
out["user_id"] = out["user_id"].astype(int)
out.to_parquet("/app/merged_users.parquet", index=False)

print(f"users: {len(out)}, conflicts: {len(conflicts)}")
print(out.to_string(index=False))

